// Accepts the legacy token NO_ORDER_SIDE as "no value", like nautilus.
[[nodiscard]] constexpr core::Status parse_optional(std::string_view text, std::optional<OrderSide>& out) noexcept {
  if (text.empty() || detail::iequals(text, "NO_ORDER_SIDE")) {
    out = std::nullopt;
    return core::Status::Ok;
  }
  OrderSide value{};
  const core::Status status = parse(text, value);
  if (core::ok(status)) {
    out = value;
  }
  return status;
}

